if(window.top!==window.self){document.getElementById("root").textContent="Abra a Conecty diretamente no navegador para continuar.";throw new Error("Framing blocked")}window.__CONECTY_AUDIENCE__="client";window.addEventListener('beforeinstallprompt',event=>{if(typeof event.prompt!=='function'||!event.userChoice)return;event.preventDefault();window.__CONECTY_EARLY_INSTALL__={audience:new URLSearchParams(location.search).get('visao')==='adm'?'admin':window.__CONECTY_AUDIENCE__,event}});window.addEventListener('appinstalled',()=>{try{const role=new URLSearchParams(location.search).get('visao')==='adm'?'admin':window.__CONECTY_AUDIENCE__;localStorage.setItem('conecty-installed-'+role,'1')}catch{}});import("../assets/demo-4C7JZKRV.js").catch(()=>{const root=document.getElementById("root");if(!root)return;root.textContent="";const main=document.createElement("main");main.className="page-recovery";const section=document.createElement("section");const title=document.createElement("h1");title.textContent="Vamos reabrir seu painel.";const message=document.createElement("p");message.textContent="Não foi possível carregar a versão desta tela. Reabra o painel para tentar novamente.";const button=document.createElement("button");button.className="button dark";button.textContent="Reabrir painel";button.addEventListener("click",()=>window.location.reload());section.append(title,message,button);main.append(section);root.append(main)});